// Builds AppIcon.appiconset from icon-source/art.png (generated by Codex
// imagegen): the art is placed on the standard macOS 824/1024 squircle.
// Usage: swift make-icons.swift <art.png> <AppIcon.appiconset>
import AppKit

let args = CommandLine.arguments
let art = NSImage(contentsOfFile: args[1])!
let out = args[2]

func render(_ px: Int) -> Data {
    let size = CGFloat(px)
    let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: px, pixelsHigh: px, bitsPerSample: 8,
                               samplesPerPixel: 4, hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB,
                               bytesPerRow: 0, bitsPerPixel: 0)!
    NSGraphicsContext.saveGraphicsState()
    NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
    NSGraphicsContext.current?.imageInterpolation = .high
    let body = NSRect(x: 0, y: 0, width: size, height: size).insetBy(dx: size * 100 / 1024, dy: size * 100 / 1024)
    let radius = body.width * 0.2237
    NSColor(white: 0, alpha: 0.12).setFill()
    NSBezierPath(roundedRect: body.offsetBy(dx: 0, dy: -size * 0.012), xRadius: radius, yRadius: radius).fill()
    let tile = NSBezierPath(roundedRect: body, xRadius: radius, yRadius: radius)
    NSColor.white.setFill()
    tile.fill()
    tile.addClip()
    art.draw(in: body.insetBy(dx: body.width * 0.06, dy: body.width * 0.06))
    NSGraphicsContext.restoreGraphicsState()
    return rep.representation(using: .png, properties: [:])!
}

for (points, scale) in [(16, 1), (16, 2), (32, 1), (32, 2), (128, 1), (128, 2), (256, 1), (256, 2), (512, 1), (512, 2)] {
    let name = "icon_\(points)x\(points)\(scale == 2 ? "@2x" : "").png"
    try! render(points * scale).write(to: URL(fileURLWithPath: "\(out)/\(name)"))
}
